/* @lc app=leetcode id=3411 lang=kotlin */ class Solution { fun g(a: Long, b: Long): Long = if (b == 0L) a else g(b, a % b) fun maxLength(nums: IntArray): Int = nums.indices.maxOf { i -> (i until nums.size).maxOf { j -> nums.slice(i..j).map { it.toLong() }.let { s -> if (s.fold(java.math.BigInteger.ONE) { a, b -> a * b.toBigInteger() } == (s.fold(0L) { a, b -> g(a, b) } * s.fold(1L) { l, x -> l / g(l, x) * x }).toBigInteger()) j - i + 1 else 0 } } } }